package com.library;
import org.apache.ibatis.annotations.*; import java.util.*;
@Mapper public interface BookMapper { @Select("<script>SELECT * FROM book WHERE 1=1 <if test='bookName != null and bookName != \"\"'>AND (book_name LIKE CONCAT('%',#{bookName},'%') OR author LIKE CONCAT('%',#{bookName},'%'))</if> <if test='categoryId != null and categoryId &gt; 0'>AND category_id=#{categoryId}</if> ORDER BY id DESC</script>") List<Book> findAll(Book condition); @Select("SELECT * FROM book WHERE id=#{id}") Book findById(Long id); @Insert("INSERT INTO book(book_name,author,price,category_id,stock,version) VALUES(#{bookName},#{author},#{price},#{categoryId},#{stock},0)") @Options(useGeneratedKeys=true,keyProperty="id") int insert(Book b); @Update("UPDATE book SET book_name=#{bookName},author=#{author},price=#{price},category_id=#{categoryId},stock=#{stock},version=version+1 WHERE id=#{id}") int update(Book b); @Update("UPDATE book SET stock=stock-1,version=version+1 WHERE id=#{id} AND stock>0 AND version=#{version}") int decreaseStock(@Param("id") Long id,@Param("version") Long version); @Update("UPDATE book SET stock=stock+1,version=version+1 WHERE id=#{id} AND version=#{version}") int increaseStock(@Param("id") Long id,@Param("version") Long version); @Delete("DELETE FROM book WHERE id=#{id}") int delete(Long id); }
